-- PT102-S4-Q5. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT102-S4-Q5$batch10$ AND q.stimulus=$batch10$If the ivory trade continues, experts believe, the elephant will soon become extinct in Africa, because poaching is rife in many areas. A total ban on ivory trading would probably prevent the extinction. However, the country of Zimbabwe—which has virtually eliminated poaching within its borders and which relies on income from carefully culling elephant herds that threaten to become too big—objects to such a ban. Zimbabwe holds that the problem lies not with the ivory trade but with the conservation policies of other countries.$batch10$ AND q.prompt=$batch10$Which one of the following principles forms a logical basis for Zimbabwe's objection to a ban?$batch10$ AND q.correct_choice=$batch10$A$batch10$) THEN RAISE EXCEPTION 'Question changed: PT102-S4-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT102-S4-Q5$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S4-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT102-S4-Q5$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$Zimbabwe objects to a total ban on ivory trading.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$Zimbabwe has virtually eliminated poaching inside its borders and earns income by culling herds that grow too big. Zimbabwe says the problem is not the ivory trade but other countries' conservation policies.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$Zimbabwe's case is that it isn't the cause of the problem, yet a worldwide ban would cost it the culling income. So the principle has to say that a fix aimed at a problem shouldn't hurt the countries that didn't cause it.$batch10$), (3, $batch10$Goal$batch10$, $batch10$If a country is not responsible for a problem, international measures to correct that problem should not harm it.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT102-S4-Q5$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$Zimbabwe isn't responsible for the poaching, and a ban would take away its culling income. This principle says a measure like that shouldn't adversely affect a country in Zimbabwe's position, which is exactly the basis for its objection.$batch10$), ($batch10$B$batch10$, $batch10$Where the right to trade comes from never comes up. If anything, saying trade rests on agreements among nations makes a ban agreed by nations easier to defend.$batch10$), ($batch10$C$batch10$, $batch10$Zimbabwe never argues from sovereignty. Its point is that it isn't the source of the problem, and it doesn't say saving the elephant matters less than anything.$batch10$), ($batch10$D$batch10$, $batch10$Who should enforce a ban is beside the point. Zimbabwe objects to having the ban at all.$batch10$), ($batch10$E$batch10$, $batch10$This is the most-picked wrong answer because it sounds like Zimbabwe's record. But it says only that eliminating poaching is necessary for conservation. It gives no reason why a country that already did so should escape a ban, so it doesn't support the objection.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT102-S4-Q5$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
